import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class AK375 {
    public static Scanner reader = new Scanner(System.in);
    public String analyze(int n, String str) {
        StringBuilder bufferA = new StringBuilder();
        StringBuilder bufferB = new StringBuilder();
        int maxLength = 0;
        int blockCount = 0;

        for (int i = 0; i < n; i++) {
            char c = str.charAt(i);
            if (c == '(') {
                bufferB.append('_');
                int j = i + 1;
                while (j < n && str.charAt(j) != ')') {
                    bufferB.append(str.charAt(j));
                    j++;
                }
                i = j;
            } else if (c == ')') {
                bufferA.append('_');
            } else {
                bufferA.append(c);
            }
        }

        String[] segments = bufferB.toString().split("_");
        List<String> segmentList = new ArrayList<>();
        for (String s : segments) {
            if (s != null && !s.isEmpty()) {
                segmentList.add(s);
            }
        }
        blockCount = segmentList.size();

        String[] mainParts = bufferA.toString().split("_");
        for (String part : mainParts) {
            if (part.length() > maxLength) {
                maxLength = part.length();
            }
        }
        return maxLength + " " + blockCount;
    }

    public static void main(String[] args) {
        while (reader.hasNext()) {
            int n = reader.nextInt();
            String s = reader.next();
            long startTime = System.currentTimeMillis();
            String output = new AK375().analyze(n, s);
            long endTime = System.currentTimeMillis();
            System.out.println(output);
        }
    }
}
